# Referee's one-modulus PU / ANG / SL test with independent code.
import sys, json, rlib
from fractions import Fraction as Fr
def hnf_index(vecs,r):
    """index of lattice generated by vecs in Z^r (0 if rank<r). Integer echelon via gcd row ops."""
    rows=[list(v) for v in vecs if any(v)]
    piv=[]; M=[]
    for col in range(r):
        # gather rows with nonzero in col among remaining
        while True:
            nz=[i for i,row in enumerate(rows) if row[col]!=0]
            if len(nz)<=1: break
            nz.sort(key=lambda i: abs(rows[i][col]))
            a=rows[nz[0]]
            for i in nz[1:]:
                f=rows[i][col]//a[col]
                rows[i]=[x-f*y for x,y in zip(rows[i],a)]
            rows=[row for row in rows if any(row)]
        nz=[i for i,row in enumerate(rows) if row[col]!=0]
        if not nz: return 0
        M.append(rows.pop(nz[0]))
    d=1
    for i,row in enumerate(M): d*=abs(row[i])
    return d
def J0ok(m,N):
    # Lemma J0 via Lemma 2.1, exact rationals. a_s = nu_s^2 m_s^2/N
    a=[Fr(m[0]**2,N),Fr(m[1]**2,2*N),Fr(m[2]**2,N),Fr(m[3]**2,2*N)]
    if a[0]+a[2]>1 or a[1]+a[3]>1: return 'OPP'
    if max(0,2*a[0]-1,2*a[2]-1)**2+max(0,2*a[1]-1,2*a[3]-1)**2>1: return 'ADJ'
    if max(abs(1-2*a[0]),abs(1-2*a[2]))**2+max(abs(1-2*a[1]),abs(1-2*a[3]))**2<1: return 'MAX'
    return None
def setup(P,K,F,q0):
    pis=[rlib.gpi(p) for p in P]; r=len(P)
    Fp=[q for q in F if q!=q0]
    V=rlib.VK(r,K); data={}
    for v in V:
        z=rlib.Zv(pis,v); D=rlib.Ds(z); N=z[0]**2+z[1]**2
        g=[]
        for s in range(4):
            gs=1
            for q in Fp:
                e=rlib.ordp(D[s],q)
                gs*=q**e
            g.append(gs)
        data[v]=(D,N,g)
    return pis,V,data
def run(P,K,F,q0,cap=3000,detail=True):
    pis,V,data=setup(P,K,F,q0); r=len(P)
    m,L=rlib.labels(pis,q0); n=m//4
    par=[x%2 for x in L]
    consPU=[];consSL=[]
    for v in V:
        D,N,g=data[v]; mkP=0; mkS=0
        for s in range(4):
            nu2N = N if s%2==0 else 2*N
            if q0*q0*g[s]*g[s] > nu2N: mkP|=1<<s
            if q0*g[s] > abs(D[s]): mkS|=1<<s
        consPU.append((v,mkP)); consSL.append((v,mkS))
    cls=rlib.classcodes(L,n)
    res={'q0':q0,'m':m}
    outP=rlib.run_enum(r,m,1,cap,par,consPU,cls)
    outS=rlib.run_enum(r,m,1,cap,par,consSL,cls)
    def parse(out):
        labs=[];cnt=None
        for line in out.splitlines():
            if line.startswith('L '): labs.append(tuple(map(int,line.split()[1:])))
            elif line.startswith('COUNT'):
                t=line.split(); cnt=(int(t[2]),int(t[4]),int(t[6]))
        return cnt,labs
    cP,lP=parse(outP); cS,lS=parse(outS)
    res['PU']=cP; res['SL0']=cS
    # P0 / triple lattice
    P0=set(v for v in V if data[v][2][1]==abs(data[v][0][1]) and data[v][2][3]==abs(data[v][0][3]))
    T=set()
    for v in P0:
        for w in P0:
            u=tuple(a+b for a,b in zip(v,w))
            if any(u) and u in P0: T.update([v,w,u])
    res['P0']=len(P0); res['T']=len(T); res['index']=hnf_index(list(T),r)
    if detail and cP[2]<=3000:
        prof={}; ang=0; slphi0=0; a1labels=[]
        for c in lP:
            types={}; j0fail=False; allC=True; hasA1=False
            for v in V:
                s=sum(a*b for a,b in zip(v,c))%m
                D,N,g=data[v]
                if s%n: 
                    continue
                sp=s//n
                U=[abs(D[t])//g[t] for t in range(4)]
                if q0<=U[sp]: ty='C'
                elif U[(sp+2)%4]==1: ty='A0'
                else: ty='A1'
                types[ty]=types.get(ty,0)+1
                if ty!='C': allC=False
                if ty=='A1': hasA1=True
                mm=list(g); mm[sp]*=q0
                if J0ok(mm,N): j0fail=True
            key=tuple(sorted(types.items()))
            prof[key]=prof.get(key,0)+1
            if not j0fail: ang+=1
            if allC: slphi0+=1
            if hasA1 and not j0fail: a1labels.append(c)
        res['profiles']={str(k):v for k,v in prof.items()}
        res['ANG_out']=ang; res['SLphi0_out']=slphi0; res['A1_ANG']=len(a1labels)
        assert slphi0==cS[2], (slphi0,cS)
    res['SLlabels']=lS[:50]
    return res
if __name__=='__main__':
    P=json.loads(sys.argv[1]); K=int(sys.argv[2]); F=json.load(open(sys.argv[3]))['F']; qs=json.loads(sys.argv[4])
    for q0 in qs:
        r=run(P,K,F,q0)
        r.pop('SLlabels')
        print(json.dumps(r),flush=True)
